script:
# Wide Motion
# How it sounds: Opposite-phase AM L/R for width.
# a Rate: 0.08 to 2.5, default 0.35
# b Depth: 0.15 to 0.7, default 0.42
# c Drive: 1 to 2.6, default 1.45

param a = Rate [0.08, 2.5]
param b = Depth [0.15, 0.7]
param c = Drive [1.0, 2.6]
osc1: shape = sine; freq = a; depth = 1.0  # LFO
split1: type = leftright {
  left {
    stage1: y = tube(x, c) * (1.0 - b + b * (0.5 + 0.5 * osc1))  # tube saturation
  }
  right {
    stage2: y = tube(x, c) * (1.0 - b + b * (0.5 - 0.5 * osc1))  # tube saturation
  }
}

# MS Width
# How it sounds: True mid/side stereo width: encode, scale side, decode.
# a Width: 0 to 1.6, default 1
# b Level: 0.7 to 1.2, default 1

param a = Width [0.0, 1.6]
param b = Level [0.7, 1.2]
split1: type = midside {
  mid {
    stage1: y = x * b  # waveshape / mix
  }
  side {
    stage2: y = x * a * b  # waveshape / mix
  }
}

# MS Mid Focus
# How it sounds: Compress the mid, leave side open — focused center with width.
# a Threshold: -30 to -8, default -18
# b Ratio: 1.5 to 6, default 2.8
# c Side: 0.7 to 1.35, default 1.05
# d Makeup: 0.9 to 1.4, default 1.1

param a = Threshold [-30.0, -8.0]
param b = Ratio [1.5, 6.0]
param c = Side [0.7, 1.35]
param d = Makeup [0.9, 1.4]
split1: type = midside {
  mid {
    stage1: y = x  # waveshape / mix
    comp1: threshold = a; ratio = b; attack = 0.012; release = 0.16  # compressor
    stage2: y = softclip(x * d, 1.08)  # soft clip
  }
  side {
    stage3: y = softclip(x * c, 1.05)  # soft clip
  }
}

# Wet Dry Split Guitar
# How it sounds: Left stays drier amp, right is delayed wet. Stereo DI / dual cab feel.
# a Drive: 1 to 6, default 2.8
# b Wet: 0.15 to 0.6, default 0.32
# c Time: 12 to 40, default 22

param a = Drive [1, 6]
param b = Wet [0.15, 0.6]
param c = Time [12, 40]
split1: type = leftright {
  left {
    stage1: y = tube(x, a * 0.7)  # tube saturation
    ir1: mix = 0.4; gain = 0  # impulse response
  }
  right {
    delay1: time = c; feedback = 0.05; mix = b; damp = 5000  # delay line
    stage2: y = tube(x, a)  # tube saturation
    ir2: mix = 0.45; gain = 1  # impulse response
  }
}
